// Recoge datos del webhook
const d = $input.first().json;
const KEY = $vars.FIRECRAWL_API_KEY;

// Scraping de una URL via Firecrawl
async function scrape(url) {
  if (!url) return null;
  try {
    const res = await fetch('https://api.firecrawl.dev/v1/scrape', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${KEY}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        url,
        formats: ['markdown'],
        onlyMainContent: true,
        timeout: 15000
      })
    });
    const json = await res.json();
    if (!json.success) return `[Error Firecrawl: ${json.error || 'sin detalle'}]`;
    // Limitar a 3000 chars para no saturar Claude
    const content = json.data?.markdown ?? '';
    return content.slice(0, 3000) || '[Contenido vacío]';
  } catch (e) {
    return `[Error de red: ${e.message}]`;
  }
}

// Scraping en paralelo de todas las URLs
const [googleContent, igContent, webContent, portalContent] = await Promise.all([
  scrape(d.google_business_url),
  scrape(d.instagram_url),
  scrape(d.website),
  scrape(d.portal_url)
]);

return [{
  json: {
    ...d,
    scraped: {
      google:    googleContent,
      instagram: igContent,
      website:   webContent,
      portal:    portalContent
    }
  }
}];

// Extrae el texto del informe de la respuesta de Claude
const claudeResp = $input.first().json;
const report = claudeResp.content?.[0]?.text ?? 'Error: no se pudo generar el informe.';

// Recupera los datos completos del nodo de Firecrawl
const original = $('Firecrawl — Investigar URLs').first().json;

return [{
  json: {
    ...original,
    investigation_report: report,
    updated_at: new Date().toISOString()
  }
}];

